Translate("ruRU", "caverns-of-time", {
	title = "Пещеры Времени",
	sections = {
		{
			title = "Обзор",
			text = [=[В восточных горах {link:tanaris}Танарис{/link}а в скале открывается {link:ogres}огр{/link}омная пещера. Ее называют Пещерами Времени. Старые предания говорят, что это логово {red:bronze-dragonflight}бронзовых драконов{/red} и их владыки, Вневременного {red:nozdormu}Ноздорму{/red}, которому титаны поручили стеречь пути времени. Ни один путник наших дней не рассказал, что лежит внутри.]=],
		},
	},
})

Translate("ruRU", "valley-of-the-watchers", {
	title = "Долина Стражей",
	aliases = { "Ульдум", "запечатанные врата Ульдума" },
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Стражей лежит на юго-западе {link:tanaris}Танарис{/link}а. Там в песке стоят исполинские каменные изваяния титанов, а между ними высятся {link:ogres}огр{/link}омные запечатанные врата. Ученые {link:thunder-bluff}Громового Утеса{/link} полагают, что врата ведут в Ульдум — место, которое большинство считает мифом. Перед вратами стоит пьедестал. Когда к нему приносят платиновые диски {link:uldaman}Ульдамана{/link}, является каменный страж титана Норганнона и отказывает во входе всем, у кого нет Пластин Ульдума. Неподалеку, на Заставе Ганстена, держит свой лагерь старатель {link:explorers-league}Лиги исследователей{/link}.]=],
		},
	},
})

Translate("ruRU", "thistleshrub-valley", {
	title = "Долина Кактусов",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Кактусов — кактусовый сад на западе {link:tanaris}Танарис{/link}а, где дюны встречаются со скалами под {link:un-goro-crater}Кратером Ун'Горо{/link}. Его растения ходят. Узловатые колючие кусты и их корневики стерегут долину, а сборщики росы запасают воду в своих железах. Именно из такой железы {link:marin-noggenfogger}Марин Гогельмогель{/link} сварил свой эликсир. Тролль {link:tran-rek}Тран'рек{/link} давно мечтает попасть в долину, но не настолько, чтобы отправиться туда самому.]=],
		},
	},
})

Translate("ruRU", "eastmoon-ruins", {
	title = "Руины Восточной Луны",
	aliases = { "Руины Южной Луны" },
	sections = {
		{
			title = "Обзор",
			text = [=[Руины Восточной Луны и Руины Южной Луны — остатки селений троллей в середине пустыни, далеко к югу от Зул'Фаррака. От их народа не осталось ничего, кроме разбитого камня. Искатели сокровищ откапывают здесь маленькие резные фигурки гидры Газ'риллы из странного камня, который гоблин {link:marvon-rivetseeker}Марвон Искатель Заклепок{/link} называет Газ'ридианом. В эти дни в руины перебрались бродячие шайки {link:ogres}огр{/link}ов Песчаного Молота.]=],
		},
	},
})

Translate("ruRU", "broken-pillar", {
	title = "Разбитая Колонна",
	sections = {
		{
			title = "Обзор",
			text = [=[Разбитая Колонна — одинокая руина в сердце {link:tanaris}Танарис{/link}а, расколотый столп, оставленный древними строителями-троллями. Здесь разбил свой лагерь ученый гоблин {link:marvon-rivetseeker}Марвон Искатель Заклепок{/link}. Он приехал в пустыню из {link:ratchet}Кабестана{/link}, чтобы узнать, чему могут научить ее павшие города троллей, и путнику, который хочет услышать о {link:temple-of-atal-hakkar}Затонувшем храме{/link}, придется искать его здесь.]=],
		},
	},
})

Translate("ruRU", "sandsorrow-watch", {
	title = "Застава Скорбных Песков",
	sections = {
		{
			title = "Обзор",
			text = [=[Застава Скорбных Песков — аванпост троллей на северо-западе {link:tanaris}Танарис{/link}а, между {link:gadgetzan}Прибамбасск{/link}ом и Зул'Фарраком. {link:sandfury-trolls}Тролли Песчаной Бури{/link} держат ее как сторожевой пост своего города. Рядом с ней лежит один из редких в пустыне водоемов с пресной водой. Когда землемер Водной компании Прибамбасска пришел проверить этот водоем, что-то поднялось из песка и напало на него. Это был первый знак того, что насекомые запада зашли так далеко на север.]=],
		},
	},
})

Translate("ruRU", "dunemaul-compound", {
	title = "Поселение Песчаного Молота",
	sections = {
		{
			title = "Обзор",
			text = [=[Поселение Песчаного Молота — лагерь {link:ogres}огр{/link}ов в южной пустыне {link:tanaris}Танарис{/link}а. Большая шайка огров-кочевников пришла сюда недавно и огородила стеной широкую полосу песка. Их предводитель — {link:gor-marok-the-ravager}Гор'марок Опустошитель{/link}. Из поселения по пустыне расходятся шайки поменьше. {link:gadgetzan}Прибамбасск{/link} боится, что огры копят силы, и хорошо заплатил бы, чтобы их разбили прежде, чем они их накопят.]=],
		},
	},
})

Translate("ruRU", "the-noxious-lair", {
	title = "Ядовитый улей",
