Translate("ruRU", "the-gaping-chasm", {
	title = "Зияющая бездна",
	sections = {
		{
			title = "Обзор",
			text = [=[Зияющая бездна — глубокий разлом в песках к юго-востоку от {link:gadgetzan}Прибамбасск{/link}а. Насекомые Центипаар устроили в нем второй улей, и это показало гоблинам, что они держат не одну область пустыни, а две. Младший землемер Скримшенк отправился наносить бездну на карту и не вернулся. Нашли только его землемерное снаряжение. У ее края разбился и {link:gnomes}гном{/link}ский робот-искатель, далеко от своего создателя в Пиратской бухте.]=],
		},
	},
})

Translate("ruRU", "waterspring-field", {
	title = "Родниковое поле",
	sections = {
		{
