})

Translate("ruRU", "southsea-pirates", {
	title = "Пираты Южных морей",
	aliases = { "Флибустьеры Южных морей" },
	sections = {
		{
			title = "Обзор",
			text = [=[Пираты Южных морей — флибустьеры южных вод. Из укромных гаваней они совершают набеги на торговые побережья {link:kalimdor}Калимдора{/link}, и их любимая добыча — суда {link:steamwheedle-cartel}картеля Хитрая Шестеренка{/link}. В {link:tanaris}Танарис{/link}е они держат Бухту Сорванных Парусов, обнесенный стеной городок на пляже к югу от Порта Картеля. Другая их шайка тревожит побережье к югу от {link:ratchet}Кабестана{/link} в {link:the-barrens}Степях{/link}.]=],
		},
		{
			title = "В эти дни",
			text = [=[Пираты Бухты Сорванных Парусов украли ром Порта Картеля и носят при себе расписания судов самого порта с пометками о том, какие корабли дали хорошую добычу, а какие крепко дрались. Их капитана, {link:andre-firebeard}Андре Огнебород{/link}а, разыскивают вместе {link:steamwheedle-port}Порт Картеля{/link} и {link:gadgetzan}Прибамбасск{/link}. Говорят, что Картель когда-то платил пиратам, чтобы те не трогали его корабли, и что пираты начали брать деньги и все равно нападать.]=],
		},
	},
})

Translate("ruRU", "sandfury-trolls", {
	title = "Тролли Песчаной Бури",
	aliases = { "Песчаная Буря", "племя Песчаной Бури" },
	sections = {
		{
			title = "Обзор",
			text = [=[Песчаная Буря — тролли пустыни. Их город — {red:zul-farrak}Зул'Фаррак{/red} на северо-западе {link:tanaris}Танарис{/link}а, а их воины несут стражу на аванпостах, таких как {link:sandsorrow-watch}Застава Скорбных Песков{/link}. Они известны жестокостью и темной мистикой, которая поднимает их мертвецов им на службу. Они поклоняются {link:ogres}огр{/link}омной гидре Газ'рилле, которую вызывают из священного водоема в сердце своего города.]=],
		},
		{
			title = "Их ремесла",
			text = [=[Тролли Песчаной Бури делают из песчаника пустыни закалочный состав, который ценят кузнецы, знающие толк в металле. В их городе роятся скарабеи, ибо там ни один тролль не охотится на них ради панцирей. Старые таблички пророка Мош'ару, давным-давно принесенные туда, хранят их жрецы.]=],
		},
		{
			title = "В эти дни",
			text = [=[У троллей Песчаной Бури нет друзей в пустыне. Гоблины-кузнецы и ученые платят за то, что удается вынести из их города, и отряды искателей сокровищ отправляются туда за его богатствами. Выходят оттуда не все.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись наших дней не говорит, как давно тролли Песчаной Бури держат Зул'Фаррак и какие узы связывают их с другими племенами троллей.]=],
		},
	},
})

Translate("ruRU", "marin-noggenfogger", {
	title = "Марин Гогельмогель",
	subtitle = "Владыка Прибамбасска",
	found = "Прибамбасск, в сердце города",
	hint = "Ищите гоблина, который управляет Прибамбасском.",
	allegiance = "Прибамбасск · Картель Хитрая Шестеренка",
	aliases = { "Гогельмогель" },
	sections = {
		{
			title = "Обзор",
			text = [=[Марин Гогельмогель — гоблин, хозяин {link:gadgetzan}Прибамбасск{/link}а, города, который {link:steamwheedle-cartel}картель Хитрая Шестеренка{/link} возвел в пустыне {link:tanaris}Танарис{/link}. Как {link:baron-revilgaz}барон Ревилгаз{/link} правит {link:booty-bay}Пиратской бухтой{/link}, а {link:gazlowe}Газлоу{/link} надзирает за {link:ratchet}Кабестаном{/link}, так Гогельмогель держит пустынный город Картеля. Он беспокоен, вечно хочет пить и всегда охотится за следующей великой идеей. Даже друзья называют его чудаком.]=],
		},
		{
			title = "Значение",
			text = [=[{link:gadgetzan}Прибамбасск{/link} стоит на единственной безопасной воде на много лиг вокруг, и его хозяин правит на перекрестке всех дорог юга. При нем город остался ничьей землей. {link:alliance}Альянс{/link} и {link:horde}Орда{/link} равно отдыхают за его стенами, а вышибалы города хранят мир. Его имя известно и далеко за пределами пустыни — благодаря эликсиру, который его носит и на котором он намерен разбогатеть.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он управляет {link:gadgetzan}Прибамбасск{/link}ом от имени картеля {link:steamwheedle-cartel}Хитрая Шестеренка{/link}.
• Он услышал о странных созданиях пустыни, которые запасают воду в железах, и задумал сварить из них напиток.
• С помощью своей приятельницы Капельки он создал эликсир, носящий его имя.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, как Гогельмогель стал править {link:gadgetzan}Прибамбасск{/link}ом и кто правил им до него.]=],
		},
	},
	chapters = {
		{
			title = "Жаждущий гоблин",
			hint = [=[Принесите жаждущему хозяину Прибамбасска то, что скрывает кактусовый сад.]=],
			text = [=[Жажда хозяина города была так велика, что он дошел до отчаяния. Он слышал о сборщиках росы из Долины Кактусов и рассудил, что вода в их железах, может быть, наконец ее утолит. Когда ему принесли полную железу, он тут же ее выпил. Вкус был ужасен. Он едва не сдался, пока не решил, что питье настолько скверное должно хотя бы ударять в голову.]=],
		},
		{
			title = "Эликсир",
			hint = "Помогите гоблину довести его напиток до совершенства.",
			text = [=[{link:sprinkle}Капелька{/link}, повариха {link:gadgetzan}Прибамбасск{/link}а, знала секрет: фиолетовый гриб, что растет под водой небольшого озера во {link:the-hinterlands}Внутренних землях{/link}. Растертый в порошок и смешанный с росой, он сделал отвар не просто годным для питья, а чудесным. Гогельмогель объявил, что заработает на нем миллионы. Услышав, что он должен поварихе услугу, он назвал ее большой шутницей.]=],
		},
	},
	mentions = {
		{ text = "Со вкусом" },
		{ text = "Секретный ингредиент поварихи Капельки" },
		{ text = "Доставка для хозяина города" },
	},
	bonds = {
		{ id = "sprinkle", name = "Капелька", note = "его приятельница и повариха" },
		{ id = "chief-engineer-bilgewhizzle", name = "Главный инженер Трюмосвист", note = "ведает водой города" },
		{ id = "baron-revilgaz", name = "Барон Ревилгаз", note = "правит Пиратской бухтой для того же Картеля" },
		{ id = "gazlowe", name = "Газлоу", note = "правит Кабестаном для того же Картеля" },
	},
})

Translate("ruRU", "yeh-kinya", {
	title = "Йе'кинья",
	subtitle = "Знаток пророчеств троллей",
	found = "Порт Картеля",
