	allegiance = "Неизвестно",
	sections = {
		{
			title = "Обзор",
			text = [=[Йе'кинья — тролль, живущий среди гоблинов Порта Картеля. Старые предания своего народа он знает лучше многих, а более всего — предание о мертвом боге крови, Свежевателе Душ {link:hakkar}Хаккаре{/link}. Он говорит, что не верит рассказам о возвращении этого бога. Но он верит, что сущность бога таит великую силу, и взялся ее собрать.]=],
		},
		{
			title = "Значение",
			text = [=[Именно Йе'кинья привел в движение историю с Яйцом бога {link:hakkar}Хаккар{/link}а. Через духов зверей, таблички мертвого пророка и яйцо, спрятанное в городе троллей, он узнал, как можно поймать и удержать сущность Свежевателя Душ. Он говорит, что хочет уберечь ее от тех, кто употребил бы ее во зло. Верят ему не все.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он искал духов долинных крикунов {link:feralas}Фераласа{/link}, которых называет родичами одного древнего бога.
• Он добыл в {red:zul-farrak}Зул'Фарраке{/red} первые две таблички пророка Мош'ару и сплавил их воедино.
• Он послал за древним яйцом из {link:jintha-alor}Джинта'Алора{/link}, реликвией империй троллей.
• Он отправил яйцо в {link:temple-of-atal-hakkar}Храм Атал'Хаккара{/link}, где была поймана сущность бога.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не говорит, из какого племени Йе'кинья и почему он живет среди гоблинов.]=],
		},
	},
	chapters = {
		{
			title = "Духи крикунов",
			hint = "Принесите троллю из Порта Картеля духов крикунов Фераласа.",
			text = [=[Йе'кинья хотел получить духов долинных крикунов, ибо считал, что они связаны с неким древним богом. Когда их принесли, он рассказал о старом пророчестве троллей: мертвый бог {link:hakkar}Хаккар{/link} однажды вернется в мир. Одни тролли говорят, что это принесет славу. Другие говорят, что это принесет конец всему.]=],
		},
		{
			title = "Пророчество Мош'ару",
			hint = "Принесите троллю таблички пророка из Зул'Фаррака.",
			text = [=[Пророчество Мош'ару было записано на двух табличках и унесено в Зул'Фаррак. Одну держал мертвый тролль Тека Мученик, другую — гидромантка Велрата у священного водоема. Йе'кинья сплавил таблички и прочел их тайну: древнее яйцо способно вместить сущность, которой обладает {link:hakkar}Хаккар{/link}.]=],
		},
		{
			title = "Яйцо бога Хаккара",
			hint = "Отнесите яйцо в затонувший храм и верните его полным.",
			text = [=[Яйцо нашли в {link:jintha-alor}Джинта'Алор{/link}е и отнесли в Святилище Павшего Бога. Аватара бога {link:hakkar}Хаккар{/link}а явилась и пала, и ее сущность была запечатана в яйце. Когда яйцо вернулось в {link:tanaris}Танарис{/link}, в нем зашевелилась жизнь. Йе'кинья казался потрясенным и поклялся уберечь его от злых рук.]=],
		},
		{
			title = "Утраченные таблички",
			hint = "Выслушайте, что узнал дворф из Порта Картеля.",
			text = [=[Дворф-старатель, стоящий в нескольких шагах от тролля, тоже изучал это пророчество. Он говорит, что табличек Мош'ару шесть, а не две, и что тролль рассказал не всю правду.]=],
		},
	},
	mentions = {
		{ text = "Древнее яйцо" },
	},
	bonds = {
		{ id = "hakkar", name = "Хаккар", note = "бог, чью сущность он собирает" },
		{ id = "avatar-of-hakkar", name = "Аватара бога Хаккара", note = "чья сущность наполняет его яйцо" },
		{ id = "prospector-ironboot", name = "Старатель Железный Башмак", note = "сомневается в его слове" },
	},
})

Translate("ruRU", "senior-surveyor-fizzledowser", {
	title = "Старший землемер Физзлдаузер",
	subtitle = "Водная компания Прибамбасска",
	found = "Прибамбасск, на западной стороне города",
	hint = [=[Ищите гоблина, который обследует пустыню в поисках новой воды.]=],
	allegiance = "Водная компания Прибамбасска · Прибамбасск",
	aliases = { "Физзлдаузер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Старший землемер Физзлдаузер руководит поисками воды в пустыне для Водной компании {link:gadgetzan}Прибамбасск{/link}а. Раз колодцы держат {link:wastewander-nomads}кочевники{/link}, он рассылает младших землемеров в пески с лозоходными приборами искать ничейные водоемы и родники. То, что они нашли, — угроза куда большая, чем любой кочевник.]=],
		},
		{
			title = "Значение",
			text = [=[Физзлдаузер — тот гоблин, который первым поднял тревогу из-за насекомых {link:tanaris}Танарис{/link}а. Поначалу он отмахивался от сообщений о странных жуках, высасывающих воду, как от очередной уловки кочевников. Потом его землемеры начали гибнуть. Его отчеты и отчеты алхимика {link:alchemist-pestlezugg}Пестлезугг{/link}а донесли имя {link:qiraji}силитидов{/link} из {link:gadgetzan}Прибамбасск{/link}а до {link:orgrimmar}Оргриммара{/link} и {link:darnassus}Дарнасса{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он послал землемера проверить водоем у Заставы Скорбных Песков, где случилось первое нападение насекомых.
• Он велел собрать для изучения части тел насекомых Ядовитого улья.
• Он потерял в Зияющей бездне своего лучшего помощника, младшего землемера Скримшенка.
• Он согласился даром делиться отчетом о насекомых, вопреки всем привычкам своего ремесла.]=],
		},
	},
	chapters = {
		{
			title = "Обследование воды",
			hint = [=[Возьмите для Водной компании пробу из водоема у сторожевой башни троллей.]=],
			text = [=[На землемера, который пошел к водоему у Заставы Скорбных Песков, напала из засады тварь, вылезшая из песка. Физзлдаузер признался, что слышал о таких тварях. Он не верил. Теперь поверил и боялся того, что это значит для компании.]=],
		},
		{
			title = "Искупление землемера Скримшенка",
			hint = "Узнайте, что стало с землемером, пропавшим в Зияющей бездне.",
			text = [=[Скримшенк ушел в Зияющую бездну, и в его последнем донесении говорилось, что насекомых там еще больше. Вернулось только его землемерное снаряжение. Физзлдаузер сам привел в порядок вещи молодого гоблина. Записи, которые тот оставил, наводили на мысль, что насекомыми, возможно, управляет некая третья сила.]=],
		},
		{
